import{_ as a,o as s,c as t,a0 as i}from"./chunks/framework.BQvjZmTX.js";const k=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started.md","filePath":"getting-started.md"}'),n={name:"getting-started.md"};function h(l,e,r,o,d,c){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>Install the <code>arca</code> CLI, seal your first secret in the local age-encrypted vault, and run a command that uses it — without the value ever touching your terminal, a file, or an agent&#39;s context.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><p>The crates.io name <code>arca</code> belongs to an unrelated project — install from the repo:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/9aia/arca</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> arca</span></span></code></pre></div><p>From a checkout of this repo: <code>cargo xtask install</code> builds and installs the release binary to <code>~/.cargo/bin/arca</code>. For a lean binary without the TUI: <code>cargo install --git https://github.com/9aia/arca arca --no-default-features</code>.</p><h2 id="bootstrap" tabindex="-1">Bootstrap <a class="header-anchor" href="#bootstrap" aria-label="Permalink to &quot;Bootstrap&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arca</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span></code></pre></div><p><code>init</code> stores your age identity where it&#39;s safest available and verifies the vault at <code>~/.local/share/arca/vault.age</code> opens. It&#39;s idempotent — run it any time.</p><p>On a desktop session (GNOME Keyring, KeePassXC, KDE Wallet, macOS Keychain, Windows Credential Manager) the identity lands in the session keyring — it unlocks with login, no prompt. On headless boxes with no session store, <code>init</code> falls back to the <code>~/.config/arca/identity.txt</code> keyfile (mode <code>0600</code>) with a note saying so. <code>arca init --with-file</code> forces the keyfile; pinning <code>ARCA_IDENTITY_FILE</code> or <code>[vaults.*].identity</code> in config does the same — that&#39;s the headless/CI path.</p><p>Already have an <code>identity.txt</code>? <code>arca init</code> imports it into the keyring rather than orphaning it, and leaves the file as a backup you can delete when ready.</p><h2 id="seal-a-secret" tabindex="-1">Seal a secret <a class="header-anchor" href="#seal-a-secret" aria-label="Permalink to &quot;Seal a secret&quot;">​</a></h2><p>Values never enter via CLI arguments — they would land in shell history and <code>/proc</code>. Pipe them instead:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">printf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;%s&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$STRIPE_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> arca</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> put</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> arca://billing/stripe</span></span></code></pre></div><p>Interactive humans get a hidden <code>/dev/tty</code> prompt instead of stdin. The value is encrypted to your identity and stored under the <code>dev</code> env (the default context).</p><h2 id="declare-the-surface" tabindex="-1">Declare the surface <a class="header-anchor" href="#declare-the-surface" aria-label="Permalink to &quot;Declare the surface&quot;">​</a></h2><p><code>[secrets]</code> in <code>arca.toml</code> bounds what <code>run</code>/<code>env</code> may inject — least privilege, no ambient vault dump:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">secrets</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">STRIPE_KEY = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;arca://billing/stripe&quot;</span></span></code></pre></div><p>Config search: <code>./arca.toml</code> → <code>~/.config/arca/arca.toml</code> (<code>--config</code>/<code>$ARCA_CONFIG</code> override). No file at all is fine — defaults are the local vault and the <code>dev</code> env.</p><h2 id="run-with-secrets" tabindex="-1">Run with secrets <a class="header-anchor" href="#run-with-secrets" aria-label="Permalink to &quot;Run with secrets&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arca</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;curl -H &quot;Authorization: Bearer $STRIPE_KEY&quot; \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    https://api.stripe.com/v1/charges&#39;</span></span></code></pre></div><p><code>run</code> resolves the declared refs, injects them as env vars into the child only, and exits with the child&#39;s code. One arg after <code>--</code> runs via <code>bash -c</code> (shell syntax, as above); several args exec <code>argv[0]</code> directly with no shell. The value lives only in that process — agents never see it.</p><h2 id="check-the-setup" tabindex="-1">Check the setup <a class="header-anchor" href="#check-the-setup" aria-label="Permalink to &quot;Check the setup&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arca</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>Validates the config, that the routed vaults decrypt, and that every <code>[secrets]</code> ref resolves — exit <code>1</code> on findings.</p><h2 id="agent-self-discovery" tabindex="-1">Agent self-discovery <a class="header-anchor" href="#agent-self-discovery" aria-label="Permalink to &quot;Agent self-discovery&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arca</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manifest</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # verbs, JSON shapes, env vars, audit contract (JSON)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arca</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # JSON Schema for arca.toml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arca</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ver</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">b</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # every verb, self-documenting</span></span></code></pre></div><p><code>--json</code> is honored on every verb; errors are <code>{&quot;error&quot;: &quot;…&quot;}</code> on stderr with a non-zero exit. The <a href="https://github.com/9aia/arca/tree/main/.agents/skills/arca" target="_blank" rel="noreferrer">arca skill</a> teaches agents the verbs.</p><h2 id="where-next" tabindex="-1">Where next <a class="header-anchor" href="#where-next" aria-label="Permalink to &quot;Where next&quot;">​</a></h2><ul><li><a href="./tutorials/first-secret.html">Your first secret</a> — a guided end-to-end in a throwaway HOME.</li><li><a href="./how-to/inject-into-a-process.html">Inject into a process</a> — run modes, ad-hoc <code>-s</code> pairs, the <code>eval &quot;$(arca env)&quot;</code> human path.</li><li><a href="./explanation/threat-model.html">The threat model</a> — what arca does and does not protect against.</li><li><a href="./reference/cli.html">CLI reference</a> — the full verb surface.</li></ul>`,30)])])}const g=a(n,[["render",h]]);export{k as __pageData,g as default};
